  const acc=state.v154UniformAccount||await getAccount(state.parentStudent.id),net=netV151(acc),total=unit*qty,use=Boolean(state.v154UniformUseBalance),credit=use?Math.min(Math.max(0,net),total):0,debt=Math.max(0,-net),external=total-credit+debt,after=net+external-total;
