// Usa os dados salvos do comprador em todos os pedidos e habilita o mesmo planejador para a secretaria.
async function reviewParentOrderV150(){
  const {chosen,total}=updateOrderTotalV150();if(!chosen.length)return alert('Selecione ao menos um dia.');
  const student=state.v151OrderStudent||state.parentStudent;if(!student)return alert('Aluno não identificado.');
  const acc=await getAccount(student.id),net=netV151(acc),staff=state.v151OrderContext==='staff';
  if(staff&&typeof state.v151Sale?.usarSaldo==='boolean')state.v154OrderUseBalance=state.v151Sale.usarSaldo;
  if(typeof state.v154OrderUseBalance!=='boolean')state.v154OrderUseBalance=false;
  if(net<=0)state.v154OrderUseBalance=false;
  const payload=chosen.map(x=>({dataChave:x.date,produtoId:x.product.value,quantidade:Math.max(1,Number(x.qty.value||1))}));
  state.v150OrderPayload={modalidade:state.v150OrderMode,itens:payload};state.v154OrderReview={student,net,total,chosen,staff};renderOrderReviewV154();
}
window.reviewParentOrderV150=reviewParentOrderV150;

function orderPaymentCalcV154(){const r=state.v154OrderReview,use=Boolean(state.v154OrderUseBalance),credit=use?Math.min(Math.max(0,r.net),r.total):0,debt=Math.max(0,-r.net),external=r.total-credit+debt,after=r.net+external-r.total;return{...r,use,credit,debt,external,after}}
function renderOrderReviewV154(){
  const c=orderPaymentCalcV154(),student=c.student,staff=c.staff;
  openModal('Revisar programação',`<div class="v151-student-summary"><div class="big">${esc(student.nome)}</div><div>${esc(student.turma)} · Saldo ${signedV151(c.net)}</div></div><label class="switch-line" style="margin-top:12px"><div><strong>Usar saldo disponível</strong><div class="muted">Ative para descontar o crédito. Desativado, o saldo positivo permanece na conta.</div></div><input id="v154OrderUseBalance" type="checkbox" ${c.use?'checked':''} ${c.net<=0?'disabled':''} onchange="state.v154OrderUseBalance=this.checked;${staff?'state.v151Sale.usarSaldo=this.checked;':''}renderOrderReviewV154()"></label><div class="v150-modal-summary" style="margin-top:12px"><div><span>Entregas</span><strong>${c.chosen.length}</strong></div><div><span>Total dos lanches</span><strong>${fmt(c.total)}</strong></div><div><span>Saldo atual</span><strong>${signedV151(c.net)}</strong></div><div><span>Saldo utilizado</span><strong>${fmt(c.credit)}</strong></div>${c.debt?`<div><span>Regularização obrigatória</span><strong>${fmt(c.debt)}</strong></div>`:''}<div><span>Pagamento necessário</span><strong>${fmt(c.external)}</strong></div><div><span>Saldo estimado depois</span><strong>${signedV151(c.after)}</strong></div></div>${staff?`<div class="form-row" style="margin-top:12px"><div class="fg"><label>Forma de pagamento</label><select id="v151ScheduledMethod" class="fi" onchange="updateScheduledPaymentV151(${c.external})"><option value="dinheiro">Dinheiro</option><option value="pix_manual">Pix manual</option><option value="maquininha">Cartão na maquininha</option><option value="cartao_rede">Cartão Rede / Laranjinha</option></select></div><div class="fg"><label>Valor recebido</label><input id="v151ScheduledReceived" class="fi" value="${(c.external/100).toFixed(2).replace('.',',')}" oninput="updateScheduledPaymentV151(${c.external})"></div></div><div id="v151ScheduledChange"></div>`:`<div class="alert warn" style="margin-top:12px">O estoque de salgados será reservado por <strong>5 minutos</strong> enquanto o pagamento é concluído.</div>`}<div class="v150-planner" style="margin-top:12px;max-height:30vh">${c.chosen.map(x=>`<div class="v150-order-row"><div><strong>${datePtV151(x.date,true)}</strong><div class="muted">${esc(productById(x.product.value)?.nome||'-')} · ${x.qty.value} un.</div></div><strong>${fmt(productPrice(productById(x.product.value))*Number(x.qty.value||1))}</strong></div>`).join('')}</div><div id="v154OrderCheckoutStatus" style="margin-top:10px"></div><button id="v150ConfirmOrderBtn" class="btn btn-green" style="width:100%;margin-top:12px" onclick="submitParentOrderV151()">${staff?'Confirmar pedido e pagamento':'Reservar e continuar'}</button><button class="btn btn-outline" style="width:100%;margin-top:8px" onclick="openParentOrderV150('${state.v150OrderMode}')">Voltar e alterar</button>`);if(staff)updateScheduledPaymentV151(c.external);
}
window.renderOrderReviewV154=renderOrderReviewV154;

function updateScheduledPaymentV151(required){const rec=parseBRL($('#v151ScheduledReceived')?.value||0),diff=Math.max(0,rec-required),host=$('#v151ScheduledChange');if(!host)return;host.innerHTML=diff>0?`<div class="alert warn"><strong>Diferença: ${fmt(diff)}</strong><div style="margin-top:7px"><label><input type="radio" name="v151ScheduledChange" value="devolver" checked> Entregar como troco</label><br><label><input type="radio" name="v151ScheduledChange" value="credito"> Deixar como crédito na conta</label></div></div>`:'<div class="alert">O valor recebido fecha a operação sem troco.</div>'}
async function submitParentOrderV151(){
  const btn=$('#v150ConfirmOrderBtn'),statusHost=$('#v154OrderCheckoutStatus'),student=state.v151OrderStudent||state.parentStudent,staff=state.v151OrderContext==='staff';
  try{
    if(staff){
      const calc=orderPaymentCalcV154(),method=$('#v151ScheduledMethod').value,received=parseBRL($('#v151ScheduledReceived').value),dest=document.querySelector('input[name="v151ScheduledChange"]:checked')?.value||'devolver',actor=state.user||{};
      if(btn){btn.disabled=true;btn.textContent='Registrando...'}
      const resp=await fetch('/api/registrar-operacao-presencial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operacao:'pedido_cantina_programado',alunoId:student.id,pedido:state.v150OrderPayload,usarSaldo:Boolean(state.v154OrderUseBalance),formaPagamento:method,valorRecebidoCentavos:received,destinoTroco:dest,criadoPorId:actor.id,criadoPorNome:actor.nome,criadoPorPerfil:actor.perfil})}),data=await resp.json().catch(()=>({}));
      if(!resp.ok)throw new Error(data.error||'Não foi possível registrar o pedido.');state.v151OrderStudent=null;state.v151OrderContext=null;closeModal();toast('Pedido programado e pagamento registrado.');renderVendasV151();return;
    }
    const buyer=await getSavedBuyerV151(student.id),payload={tipo:'pedido_cantina',alunoId:student.id,usarSaldo:Boolean(state.v154OrderUseBalance),pedido:state.v150OrderPayload,comprador:{nome:buyer.name||student.responsavelFinanceiro||'',telefone:buyer.phone_number||student.celularResponsavel||'',email:buyer.email||''},criadoPorId:'portal_responsavel',criadoPorNome:student.responsavelFinanceiro||'Responsável',criadoPorPerfil:'responsavel'};
    const data=await requestCheckoutV154(payload,{button:btn,statusHost});if(data.preparando)return;
    if(data.sem_checkout){closeModal();toast(data.pedido_confirmado?'Pedido confirmado com o saldo da conta.':'Pedido enviado para revisão.');await renderParentPortal();return}
    if(!data.checkout_url)throw new Error('O link ainda não está disponível. Consulte Pagamentos pendentes.');location.href=data.checkout_url;
  }catch(e){alert(e.message)}finally{if(staff&&btn){btn.disabled=false;btn.textContent='Confirmar pedido e pagamento'}}
}
window.submitParentOrderV150=submitParentOrderV151;window.submitParentOrderV151=submitParentOrderV151;window.updateScheduledPaymentV151=updateScheduledPaymentV151;

// Secretaria — nova venda em modal por etapas.
async function renderVendasV151(){const el=$('#mainContent');el.innerHTML=pageHeader('Vendas da secretaria','Operações vinculadas ao aluno, com pagamento, conta corrente, pedidos e troco.',`<button class="btn btn-primary" onclick="startSecretarySaleV151()">+ Nova venda</button>`)+`<div class="grid g3"><div class="kpi"><div class="kpi-label">Nova operação</div><div class="kpi-value">Aluno</div><div class="kpi-sub">Veja saldo, limite e histórico antes de confirmar.</div></div><div class="kpi green"><div class="kpi-label">Soma zero</div><div class="kpi-value">Entrada + saída</div><div class="kpi-sub">Compras pagas passam pela conta sem alterar o saldo final.</div></div><div class="kpi orange"><div class="kpi-label">Troco</div><div class="kpi-value">Devolver ou creditar</div><div class="kpi-sub">A diferença pode ficar disponível na conta do aluno.</div></div></div><div class="card" style="margin-top:14px"><div class="card-head"><div class="card-title">Como registrar</div></div><div class="card-body"><div class="v151-operation-grid"><div class="v151-operation"><strong>Venda imediata</strong><span>Lanche entregue ou farda vendida agora.</span></div><div class="v151-operation"><strong>Programar lanches</strong><span>Dia, semana ou mês, gerando obrigações para a cantina.</span></div><div class="v151-operation"><strong>Adicionar crédito</strong><span>Entrada na conta sem criar uma compra.</span></div></div></div></div>`}
function startSecretarySaleV151(){
  state.v151Sale={step:1,student:null,account:null,operation:'venda_imediata',cart:[],usarSaldo:false,method:'dinheiro',received:0,change:'devolver'};openModal('Nova venda',`<div id="v151SaleHost"></div>`);document.querySelector('.modal')?.classList.add('v151-modal-wide');renderSecretarySaleStepV151();
}
function stepHeaderV151(step){return`<div class="v151-sale-steps">${['Aluno','Operação','Pagamento','Confirmação'].map((x,i)=>`<div class="v151-sale-step ${i+1===step?'active':''}"><b>${i+1}</b><span>${x}</span></div>`).join('')}</div>`}
async function renderSecretarySaleStepV151(){const st=state.v151Sale,host=$('#v151SaleHost');if(!host)return;if(st.step===1){host.innerHTML=stepHeaderV151(1)+`<div class="fg"><label>Pesquisar aluno por nome ou matrícula</label><input id="v151SaleStudentSearch" class="fi" autofocus oninput="searchStudentsInto(this.value,'v151SaleStudentResults','chooseSecretaryStudentV151')"></div><div id="v151SaleStudentResults" class="search-results"></div><div id="v151SaleStudentChosen">${st.student?secretaryStudentSummaryV151(st):'<div class="empty-soft">Selecione o aluno para visualizar saldo, situação e limite.</div>'}</div><div class="v151-wizard-foot"><button class="btn btn-outline" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" ${st.student?'':'disabled'} onclick="secretarySaleNextV151()">Continuar</button></div>`;return}if(st.step===2){host.innerHTML=stepHeaderV151(2)+secretaryStudentSummaryV151(st)+`<div class="v151-operation-grid" style="margin-top:12px"><button class="v151-operation ${st.operation==='venda_imediata'?'active':''}" onclick="setSecretaryOperationV151('venda_imediata')"><strong>Venda imediata</strong><span>Produto entregue ou encaminhado agora.</span></button><button class="v151-operation ${st.operation==='pedido_cantina_programado'?'active':''}" onclick="setSecretaryOperationV151('pedido_cantina_programado')"><strong>Programar lanches</strong><span>Dia, semana ou mês para a agenda da cantina.</span></button><button class="v151-operation ${st.operation==='adicionar_credito'?'active':''}" onclick="setSecretaryOperationV151('adicionar_credito')"><strong>Adicionar crédito</strong><span>Somente entrada na conta do aluno.</span></button></div><div id="v151SaleItems" style="margin-top:14px"></div><div class="v151-wizard-foot"><button class="btn btn-outline" onclick="secretarySaleBackV151()">Voltar</button><button class="btn btn-primary" onclick="secretarySaleNextV151()">Continuar</button></div>`;renderSecretaryItemsV151();return}if(st.step===3){const total=secretarySaleTotalV151(),before=netV151(st.account),credit=st.usarSaldo?Math.min(Math.max(0,before),total):0,required=st.operation==='adicionar_credito'?0:Math.max(0,total-credit),defaultReceived=st.received||required;host.innerHTML=stepHeaderV151(3)+secretaryStudentSummaryV151(st)+`<div class="v151-summary" style="margin-top:12px"><div><span>Total da compra</span><strong>${fmt(total)}</strong></div><div><span>Saldo atual</span><strong>${signedV151(before)}</strong></div><div><span>Saldo que pode ser usado</span><strong>${fmt(credit)}</strong></div><div><span>Pagamento mínimo</span><strong>${fmt(required)}</strong></div></div>${st.operation!=='adicionar_credito'?`<label class="switch-line" style="margin-top:12px"><div><strong>Usar crédito disponível</strong><div class="muted">Se desmarcado, o responsável paga a compra inteira e o saldo anterior permanece.</div></div><input id="v151UseBalance" type="checkbox" ${st.usarSaldo?'checked':''} onchange="state.v151Sale.usarSaldo=this.checked;renderSecretarySaleStepV151()"></label>`:''}<div class="form-row" style="margin-top:12px"><div class="fg"><label>Forma de pagamento</label><select id="v151SaleMethod" class="fi" onchange="state.v151Sale.method=this.value;updateSecretaryPaymentV151()"><option value="dinheiro" ${st.method==='dinheiro'?'selected':''}>Dinheiro</option><option value="pix_manual" ${st.method==='pix_manual'?'selected':''}>Pix manual</option><option value="maquininha" ${st.method==='maquininha'?'selected':''}>Cartão na maquininha</option><option value="cartao_rede" ${st.method==='cartao_rede'?'selected':''}>Cartão Rede / Laranjinha</option></select></div><div class="fg"><label>Valor recebido</label><input id="v151SaleReceived" class="fi" value="${((st.operation==='adicionar_credito'?(st.received||0):defaultReceived)/100).toFixed(2).replace('.',',')}" oninput="state.v151Sale.received=parseBRL(this.value);updateSecretaryPaymentV151()"></div></div><div id="v151SaleChange"></div><div class="v151-wizard-foot"><button class="btn btn-outline" onclick="secretarySaleBackV151()">Voltar</button><button class="btn btn-primary" onclick="secretarySaleNextV151()">Revisar</button></div>`;updateSecretaryPaymentV151();return}if(st.step===4){const calc=secretaryPaymentCalcV151();host.innerHTML=stepHeaderV151(4)+`<div class="v151-student-summary"><div class="big">${esc(st.student.nome)}</div><div>${esc(st.student.turma)} · ${st.operation==='adicionar_credito'?'Crédito na conta':'Venda presencial'}</div></div><div class="v151-summary" style="margin-top:12px"><div><span>Saldo antes</span><strong>${signedV151(calc.before)}</strong></div><div><span>Pagamento aplicado</span><strong>+ ${fmt(calc.applied)}</strong></div><div><span>${st.operation==='adicionar_credito'?'Compra':'Compra realizada'}</span><strong>${st.operation==='adicionar_credito'?fmt(0):`- ${fmt(calc.total)}`}</strong></div><div><span>Troco entregue</span><strong>${fmt(calc.returned)}</strong></div><div><span>Troco deixado como crédito</span><strong>${fmt(calc.creditChange)}</strong></div><div><span>Saldo depois</span><strong>${signedV151(calc.after)}</strong></div></div>${st.operation!=='adicionar_credito'?`<div class="card-title" style="margin:14px 0 7px">Itens</div><div>${st.cart.map(x=>`<div class="v151-cart-line"><span>${x.quantidade}× ${esc(x.nome)}</span><strong>${fmt(x.precoUnitarioCentavos*x.quantidade)}</strong><span></span></div>`).join('')}</div>`:''}<div class="alert warn" style="margin-top:12px">Confira forma de pagamento, troco e saldo final antes de concluir. A operação será vinculada ao perfil do aluno.</div><div class="v151-wizard-foot"><button class="btn btn-outline" onclick="secretarySaleBackV151()">Voltar</button><button id="v151ConfirmSale" class="btn btn-green" onclick="submitSecretarySaleV151()">Confirmar operação</button></div>`}}
function secretaryStudentSummaryV151(st){const net=netV151(st.account||{});return`<div class="v151-student-summary"><div class="big">${esc(st.student.nome)}</div><div>${esc(st.student.turma)} · Matrícula ${esc(st.student.matricula)}</div><div style="margin-top:7px">Saldo: <strong>${signedV151(net)}</strong> · Limite: <strong>${fmt(Number(st.account?.limiteFiadoCentavos||0))}</strong></div></div>`}
async function chooseSecretaryStudentV151(id){const a=state.students.find(x=>x.id===id);state.v151Sale.student=a;state.v151Sale.account=await getAccount(id);const h=$('#v151SaleStudentChosen');if(h)h.innerHTML=secretaryStudentSummaryV151(state.v151Sale);const btn=[...document.querySelectorAll('#v151SaleHost .v151-wizard-foot .btn')].pop();if(btn)btn.disabled=false;$('#v151SaleStudentResults').innerHTML='';$('#v151SaleStudentSearch').value=''}
function secretarySaleNextV151(){const st=state.v151Sale;if(st.step===1&&!st.student)return alert('Selecione o aluno.');if(st.step===2&&st.operation==='pedido_cantina_programado'){state.v151OrderStudent=st.student;state.v151OrderContext='staff';closeModal();openParentOrderV150('semanal');return}if(st.step===2&&st.operation==='venda_imediata'&&!st.cart.length)return alert('Adicione ao menos um item.');if(st.step===3){const c=secretaryPaymentCalcV151();if(st.operation==='adicionar_credito'&&c.received<=0)return alert('Informe o valor recebido.');if(st.operation!=='adicionar_credito'&&c.received<c.required)return alert(`O valor recebido precisa ser de pelo menos ${fmt(c.required)}.`)}st.step=Math.min(4,st.step+1);renderSecretarySaleStepV151()}
function secretarySaleBackV151(){state.v151Sale.step=Math.max(1,state.v151Sale.step-1);renderSecretarySaleStepV151()}
function setSecretaryOperationV151(op){state.v151Sale.operation=op;if(op==='adicionar_credito')state.v151Sale.cart=[];renderSecretarySaleStepV151()}
function renderSecretaryItemsV151(){const st=state.v151Sale,host=$('#v151SaleItems');if(!host)return;if(st.operation==='adicionar_credito'){host.innerHTML='<div class="alert">Na próxima etapa, informe quanto foi recebido e a forma de pagamento.</div>';return}if(st.operation==='pedido_cantina_programado'){host.innerHTML='<div class="alert">Ao continuar, você abrirá o mesmo planejador de dia, semana e mês usado no portal. O pagamento será registrado presencialmente.</div>';return}const products=(state.products||[]).filter(p=>p.ativo!==false&&p.vendaSecretaria!==false);host.innerHTML=`<div class="card"><div class="card-head"><div class="card-title">Produtos da cantina</div></div><div class="card-body"><div class="v151-catalog">${products.map(p=>`<button class="product-btn ${p.combo?'combo':''}" onclick="addSecretaryProductV151('${p.id}')"><strong>${esc(p.nome)}</strong><span>${fmt(productPrice(p))}</span></button>`).join('')}</div></div></div><div class="actions" style="margin-top:10px"><button class="btn btn-light" onclick="addSecretaryUniformV151()">+ Adicionar fardamento</button></div><div class="card" style="margin-top:10px"><div class="card-head"><div class="card-title">Carrinho</div><strong>${fmt(secretarySaleTotalV151())}</strong></div><div class="card-body">${st.cart.length?st.cart.map((x,i)=>`<div class="v151-cart-line"><div><strong>${esc(x.nome)}</strong><div class="muted" style="font-size:11px">${x.tipo==='farda'?`${esc(x.tamanho)} ${esc(x.modelo||'')}`:esc(x.categoria||'Cantina')}</div></div><div><button class="btn btn-outline" onclick="changeSecretaryQtyV151(${i},-1)">−</button> <strong>${x.quantidade}</strong> <button class="btn btn-outline" onclick="changeSecretaryQtyV151(${i},1)">+</button></div><button class="btn btn-outline" onclick="removeSecretaryLineV151(${i})">Remover</button></div>`).join(''):'<div class="empty-soft">Carrinho vazio.</div>'}</div></div>`}
function addSecretaryProductV151(id){const p=productById(id),found=state.v151Sale.cart.find(x=>x.tipo==='produto'&&x.produtoId===id);if(found)found.quantidade++;else state.v151Sale.cart.push({tipo:'produto',produtoId:id,nome:p.nome,categoria:p.categoria||'Cantina',quantidade:1,precoUnitarioCentavos:productPrice(p)});renderSecretaryItemsV151()}
function changeSecretaryQtyV151(i,d){const x=state.v151Sale.cart[i];x.quantidade=Math.max(1,Number(x.quantidade||1)+d);renderSecretaryItemsV151()}
function removeSecretaryLineV151(i){state.v151Sale.cart.splice(i,1);renderSecretaryItemsV151()}
function addSecretaryUniformV151(){const models=(state.uniformModels||[]).filter(x=>x.ativo!==false);if(!models.length)return alert('Nenhum modelo de farda cadastrado.');openModal('Adicionar fardamento à venda',`<div class="fg"><label>Modelo</label><select id="v151StaffUniformModel" class="fi" onchange="renderStaffUniformFieldsV151()">${models.map(x=>`<option value="${esc(x.id)}">${esc(x.nome)}</option>`).join('')}</select></div><div id="v151StaffUniformFields"></div><button class="btn btn-primary" style="width:100%" onclick="confirmSecretaryUniformV151()">Adicionar ao carrinho</button>`);renderStaffUniformFieldsV151()}
function renderStaffUniformFieldsV151(){const m=(state.uniformModels||[]).find(x=>x.id===$('#v151StaffUniformModel').value);$('#v151StaffUniformFields').innerHTML=`<div class="form-row"><div class="fg"><label>Tamanho</label><select id="v151StaffUniformSize" class="fi">${uniformSizesV151(m).map(x=>`<option>${x}</option>`).join('')}</select></div><div class="fg"><label>Modelo</label><select id="v151StaffUniformGender" class="fi"><option value="">Modelo único</option><option value="masculino">Masculino</option><option value="feminino">Feminino</option></select></div></div><div class="fg"><label>Quantidade</label><input id="v151StaffUniformQty" class="fi" type="number" min="1" value="1"></div>`}
function confirmSecretaryUniformV151(){const m=(state.uniformModels||[]).find(x=>x.id===$('#v151StaffUniformModel').value),size=$('#v151StaffUniformSize').value,adult=['P','M','G','GG','XGG'].includes(size),unit=Number(adult?(m.precoAdultoCentavos||4700):(m.precoInfantilCentavos||4200));state.v151Sale.cart.push({tipo:'farda',modeloFardaId:m.id,nome:m.nome||'Camisa de farda',tamanho:size,modelo:$('#v151StaffUniformGender').value,quantidade:Math.max(1,Number($('#v151StaffUniformQty').value||1)),precoUnitarioCentavos:unit,statusAtendimento:'aguardando_producao'});closeModal();startSecretarySaleResumeV151()}
function startSecretarySaleResumeV151(){openModal('Nova venda',`<div id="v151SaleHost"></div>`);document.querySelector('.modal')?.classList.add('v151-modal-wide');renderSecretarySaleStepV151()}
function secretarySaleTotalV151(){return(state.v151Sale?.cart||[]).reduce((s,x)=>s+Number(x.precoUnitarioCentavos||0)*Number(x.quantidade||1),0)}
function secretaryPaymentCalcV151(){
  const st=state.v151Sale,total=secretarySaleTotalV151(),before=netV151(st.account||{}),credit=st.operation==='adicionar_credito'?0:(st.usarSaldo?Math.min(Math.max(0,before),total):0),debt=st.operation==='adicionar_credito'?0:Math.max(0,-before),required=st.operation==='adicionar_credito'?0:Math.max(0,total-credit+debt),received=Number(st.received||0),diff=st.operation==='adicionar_credito'?0:Math.max(0,received-required),creditChange=st.change==='credito'?diff:0,returned=st.change==='devolver'?diff:0,applied=st.operation==='adicionar_credito'?received:required+creditChange,after=st.operation==='adicionar_credito'?before+applied:before+applied-total;return{total,before,credit,debt,required,received,diff,creditChange,returned,applied,after};
}
function updateSecretaryPaymentV151(){const st=state.v151Sale,calc=secretaryPaymentCalcV151(),host=$('#v151SaleChange');if(!host)return;if(st.operation==='adicionar_credito'){host.innerHTML=`<div class="alert">Todo o valor recebido será adicionado à conta. Saldo estimado: <strong>${signedV151(calc.after)}</strong>.</div>`;return}host.innerHTML=calc.diff>0?`<div class="alert warn"><strong>Diferença: ${fmt(calc.diff)}</strong><div style="margin-top:7px"><label><input type="radio" name="v151SaleChange" value="devolver" ${st.change==='devolver'?'checked':''} onchange="state.v151Sale.change=this.value;updateSecretaryPaymentV151()"> Entregar como troco</label><br><label><input type="radio" name="v151SaleChange" value="credito" ${st.change==='credito'?'checked':''} onchange="state.v151Sale.change=this.value;updateSecretaryPaymentV151()"> Deixar como crédito na conta</label></div><div style="margin-top:7px">Saldo estimado: <strong>${signedV151(calc.after)}</strong></div></div>`:`<div class="alert">Sem troco. Saldo estimado após a compra: <strong>${signedV151(calc.after)}</strong>.</div>`}
async function submitSecretarySaleV151(){const st=state.v151Sale,calc=secretaryPaymentCalcV151(),btn=$('#v151ConfirmSale');if(btn){btn.disabled=true;btn.textContent='Registrando...'}try{const actor=state.user||{},resp=await fetch('/api/registrar-operacao-presencial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operacao:st.operation,alunoId:st.student.id,itens:st.cart,usarSaldo:st.usarSaldo,formaPagamento:st.method,valorRecebidoCentavos:calc.received,destinoTroco:st.change,criadoPorId:actor.id,criadoPorNome:actor.nome,criadoPorPerfil:actor.perfil})}),data=await resp.json().catch(()=>({}));if(!resp.ok)throw new Error(data.error||'Não foi possível registrar a operação.');closeModal();toast('Operação registrada com sucesso.');renderVendasV151();setTimeout(()=>openStudentDetailsV143?.(st.student.id),180)}catch(e){alert(e.message);if(btn){btn.disabled=false;btn.textContent='Confirmar operação'}}}

