function renderProdutosV151(){const tab=state.v151ProductTab||'cantina',tabs=[['cantina','Cantina'],['fardas','Fardas / Fábrica'],['combos','Combos'],['inativos','Inativos']];let content='';if(tab==='fardas'){const rows=(state.uniformModels||[]);content=rows.length?rows.map(m=>`<div class="v151-product-card"><div><strong>${esc(m.nome)}</strong><div class="v151-product-meta">Tamanhos: ${uniformSizesV151(m).join(', ')} · Portal: ${m.portal===false?'não':'sim'} · ${m.ativo===false?'inativo':'ativo'}</div><div class="v151-product-meta">Infantil ${fmt(m.precoInfantilCentavos||4200)} · Adulto ${fmt(m.precoAdultoCentavos||4700)}</div></div><button class="btn btn-light" onclick="editUniformModelV151('${m.id}')">Editar</button></div>`).join(''):'<div class="empty">Nenhum modelo de farda.</div>'}else{let rows=(state.products||[]);if(tab==='cantina')rows=rows.filter(p=>p.ativo!==false&&!p.combo);if(tab==='combos')rows=rows.filter(p=>p.ativo!==false&&p.combo);if(tab==='inativos')rows=rows.filter(p=>p.ativo===false);content=rows.length?rows.map(p=>`<div class="v151-product-card"><div><strong>${esc(p.nome)}</strong><div class="v151-product-meta">${esc(p.categoria||'Cantina')} · ${p.combo?'Combo':'Produto'} · ${p.ativo===false?'Inativo':'Ativo'}</div><div class="v151-product-meta">Canais: ${p.vendaResponsavel!==false?'Portal ':''}${p.vendaSecretaria!==false?'· Secretaria ':''}${p.vendaCantina!==false?'· Cantina':''}</div></div><div style="text-align:right"><strong>${fmt(productPrice(p))}</strong><div style="margin-top:7px"><button class="btn btn-light" onclick="editProductV151('${p.id}')">Editar</button></div></div></div>`).join(''):'<div class="empty">Nenhum produto nesta área.</div>'}$('#mainContent').innerHTML=pageHeader('Produtos e catálogo','Gerencie Cantina e Fardas em ambientes separados.')+`<div class="v151-product-tabs">${tabs.map(x=>`<button class="v151-product-tab ${tab===x[0]?'active':''}" onclick="setProductTabV151('${x[0]}')">${x[1]}</button>`).join('')}</div><div class="card"><div class="card-body">${content}</div></div>`}
function editProductV151(id){const p=productById(id);openModal('Editar produto',`<div class="fg"><label>Nome</label><input id="v151ProdName" class="fi" value="${esc(p.nome)}"></div><div class="form-row"><div class="fg"><label>Categoria / área</label><input id="v151ProdCategory" class="fi" value="${esc(p.categoria||'Cantina')}"></div><div class="fg"><label>Preço</label><input id="v151ProdPrice" class="fi" value="${(productPrice(p)/100).toFixed(2).replace('.',',')}" ${p.combo?'disabled':''}></div></div><div class="grid g2"><label class="switch-line"><span>Ativo</span><input id="v151ProdActive" type="checkbox" ${p.ativo!==false?'checked':''}></label><label class="switch-line"><span>Portal do responsável</span><input id="v151ProdParent" type="checkbox" ${p.vendaResponsavel!==false&&p.portal!==false?'checked':''}></label><label class="switch-line"><span>Secretaria</span><input id="v151ProdSecretary" type="checkbox" ${p.vendaSecretaria!==false?'checked':''}></label><label class="switch-line"><span>Cantina</span><input id="v151ProdCantina" type="checkbox" ${p.vendaCantina!==false?'checked':''}></label></div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="saveProductV151('${id}',${p.combo?'true':'false'})">Salvar produto</button>`)}
async function saveProductV151(id,combo){const data={nome:$('#v151ProdName').value.trim(),categoria:$('#v151ProdCategory').value.trim()||'Cantina',ativo:$('#v151ProdActive').checked,portal:$('#v151ProdParent').checked,vendaResponsavel:$('#v151ProdParent').checked,vendaSecretaria:$('#v151ProdSecretary').checked,vendaCantina:$('#v151ProdCantina').checked,atualizadoEm:nowIso()};if(!combo)data.precoCentavos=parseBRL($('#v151ProdPrice').value);await db.collection('produtos').doc(id).set(data,{merge:true});await loadCore();closeModal();renderProdutosV151();toast('Produto atualizado.')}
function editUniformModelV151(id){const m=(state.uniformModels||[]).find(x=>x.id===id);openModal('Editar modelo de farda',`<div class="fg"><label>Nome</label><input id="v151UniformName" class="fi" value="${esc(m.nome)}"></div><div class="form-row"><div class="fg"><label>Preço infantil</label><input id="v151UniformChildPrice" class="fi" value="${((m.precoInfantilCentavos||4200)/100).toFixed(2).replace('.',',')}"></div><div class="fg"><label>Preço adulto</label><input id="v151UniformAdultPrice" class="fi" value="${((m.precoAdultoCentavos||4700)/100).toFixed(2).replace('.',',')}"></div></div><div class="grid g2"><label class="switch-line"><span>Ativo</span><input id="v151UniformActive" type="checkbox" ${m.ativo!==false?'checked':''}></label><label class="switch-line"><span>Disponível no portal</span><input id="v151UniformPortal" type="checkbox" ${m.portal!==false?'checked':''}></label></div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="saveUniformModelV151('${id}')">Salvar modelo</button>`)}
async function saveUniformModelV151(id){await db.collection('modelos_farda').doc(id).set({nome:$('#v151UniformName').value.trim(),precoInfantilCentavos:parseBRL($('#v151UniformChildPrice').value),precoAdultoCentavos:parseBRL($('#v151UniformAdultPrice').value),ativo:$('#v151UniformActive').checked,portal:$('#v151UniformPortal').checked,atualizadoEm:nowIso()},{merge:true});await loadCore();closeModal();renderProdutosV151();toast('Modelo atualizado.')}

function renderConfigV151(){$('#mainContent').innerHTML=pageHeader('Configurações','Regras gerais, Cantina, Fardamento e Conta Corrente.')+`<div class="grid g2"><div class="card"><div class="card-head"><div class="card-title">Cantina</div></div><div class="card-body"><div class="fg"><label>Salgados planejados por dia</label><input id="v151CfgSalgados" class="fi" type="number" min="0" value="${Number(state.config?.quantidadePadraoSalgados||30)}"></div><div class="fg"><label>Reserva temporária do pedido</label><input class="fi" value="5 minutos" disabled></div><div class="muted" style="font-size:12px">Pedidos pagos entram nas obrigações diárias. Reservas expiradas deixam de consumir a disponibilidade.</div></div></div><div class="card"><div class="card-head"><div class="card-title">Conta corrente</div></div><div class="card-body"><div class="fg"><label>Limite máximo de saldo em aberto</label><input id="v151CfgLimit" class="fi" value="${(Number(state.config?.limiteMaximoFiadoCentavos||5000)/100).toFixed(2).replace('.',',')}"></div><div class="fg"><label>Valor mínimo para adicionar crédito</label><input id="v151CfgMin" class="fi" value="${(Number(state.config?.valorMinimoCheckoutPositivoCentavos||100)/100).toFixed(2).replace('.',',')}"></div><label class="switch-line"><span>Bloqueio semanal na sexta-feira</span><input id="v151CfgWeekly" type="checkbox" ${state.config?.bloqueioSemanalSaldoAtivo!==false?'checked':''}></label></div></div><div class="card"><div class="card-head"><div class="card-title">Fardamento</div></div><div class="card-body"><div class="muted">Preços, modelos, tamanhos e disponibilidade no portal são administrados em <strong>Produtos e estoque → Fardas</strong>.</div></div></div><div class="card"><div class="card-head"><div class="card-title">Checkout</div></div><div class="card-body"><div class="fg"><label>Handle InfinitePay</label><input class="fi" value="piaget" disabled></div><div class="muted">Nome, telefone e e-mail do comprador são enviados a partir dos dados salvos no perfil do aluno.</div></div></div></div><button class="btn btn-primary" style="margin-top:14px" onclick="saveConfigV151()">Salvar configurações</button>`}
